item.description:
Module 1: Storage & DatabaseSet up the DynamoDB single-table for generic data storage and an S3 bucket for storing application assets.
Create lib/storage-stack.ts:
import * as cdk from 'aws-cdk-lib'; import * as dynamodb from 'aws-cdk-lib/aws-dynamodb'; import * as s3 from 'aws-cdk-lib/aws-s3'; import { Construct } from 'constructs'; export class StorageStack extends cdk.Stack { public readonly table: dynamodb.Table; public readonly assetBucket: s3.Bucket; constructor(scope: Construct, id: string, props?: cdk.StackProps) { super(scope, id, props); // Initialize DynamoDB Single Table for generic entity metadata this.table = new dynamodb.Table(this, 'AppSingleTable', { partitionKey: { name: 'PK', type: dynamodb.AttributeType.STRING }, sortKey: { name: 'SK', type: dynamodb.AttributeType.STRING }, billingMode: dynamodb.BillingMode.PAY_PER_REQUEST, // On-Demand pricing pointInTimeRecovery: true, // Enables automated backups removalPolicy: cdk.RemovalPolicy.DESTROY, // Dev environment cleanup }); // Create private S3 Bucket for application assets this.assetBucket = new s3.Bucket(this, 'AssetStorageBucket', { encryption: s3.BucketEncryption.S3_MANAGED, blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL, // Secure private bucket removalPolicy: cdk.RemovalPolicy.DESTROY, autoDeleteObjects: true, }); } }

Module 2: Compute & API GatewayWire a backend Lambda function and expose it through API Gateway. Since we are using a fully serverless architecture, the Lambda function runs in the default AWS-managed network and communicates directly with DynamoDB.
Create lib/api-stack.ts:
import * as cdk from 'aws-cdk-lib'; import * as lambda from 'aws-cdk-lib/aws-lambda'; import * as apigateway from 'aws-cdk-lib/aws-apigateway'; import * as cognito from 'aws-cdk-lib/aws-cognito'; import * as dynamodb from 'aws-cdk-lib/aws-dynamodb'; import { Construct } from 'constructs'; interface ApiStackProps extends cdk.StackProps { table: dynamodb.Table; userPool: cognito.IUserPool; } export class ApiStack extends cdk.Stack { constructor(scope: Construct, id: string, props: ApiStackProps) { super(scope, id, props); const authorizer = new apigateway.CognitoUserPoolsAuthorizer(this, 'AppApiAuthorizer', { cognitoUserPools: [props.userPool], authorizerName: 'AppAuthorizer', }); const dataLambda = new lambda.Function(this, 'DataServiceLambda', { runtime: lambda.Runtime.NODEJS_18_X, handler: 'index.handler', code: lambda.Code.fromInline(` const { DynamoDBClient } = require("@aws-sdk/client-dynamodb"); const { DynamoDBDocumentClient, ScanCommand } = require("@aws-sdk/lib-dynamodb"); const client = new DynamoDBClient({}); const docClient = DynamoDBDocumentClient.from(client); exports.handler = async (event) => { const tableName = process.env.TABLE_NAME; try { const data = await docClient.send(new ScanCommand({ TableName: tableName, FilterExpression: "begins_with(PK, :pk)", ExpressionAttributeValues: { ":pk": "ITEM#" } })); return { statusCode: 200, headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" }, body: JSON.stringify(data.Items || []) }; } catch (err) { return { statusCode: 500, body: JSON.stringify({ error: err.message }) }; } }; `), environment: { TABLE_NAME: props.table.tableName, }, }); props.table.grantReadWriteData(dataLambda); const api = new apigateway.RestApi(this, 'AppRestApi', { restApiName: 'Application Backend API', defaultCorsPreflightOptions: { allowOrigins: apigateway.Cors.ALL_ORIGINS, allowMethods: apigateway.Cors.ALL_METHODS, }, }); const itemsResource = api.root.addResource('items'); itemsResource.addMethod('GET', new apigateway.LambdaIntegration(dataLambda)); itemsResource.addMethod('POST', new apigateway.LambdaIntegration(dataLambda), { authorizer: authorizer, authorizationType: apigateway.AuthorizationType.COGNITO, }); } }

Module 3: Security & PermissionsSet up Cognito User Pool for login and create fine-grained IAM policies following the principle of Least Privilege.
Create lib/security-stack.ts:
import * as cdk from 'aws-cdk-lib'; import * as cognito from 'aws-cdk-lib/aws-cognito'; import * as iam from 'aws-cdk-lib/aws-iam'; import { Construct } from 'constructs'; export class SecurityStack extends cdk.Stack { public readonly userPool: cognito.UserPool; public readonly userPoolClient: cognito.UserPoolClient; constructor(scope: Construct, id: string, props?: cdk.StackProps) { super(scope, id, props); this.userPool = new cognito.UserPool(this, 'AppUserPool', { userPoolName: 'app-user-pool', selfSignUpEnabled: true, signInAliases: { email: true }, autoVerify: { email: true }, passwordPolicy: { minLength: 8, requireLowercase: true, requireUppercase: true, requireDigits: true, requireSymbols: true, }, removalPolicy: cdk.RemovalPolicy.DESTROY, }); this.userPoolClient = new cognito.UserPoolClient(this, 'AppUserPoolClient', { userPool: this.userPool, generateSecret: false, }); // Custom role for notification system (Least Privilege) const notificationRole = new iam.Role(this, 'NotificationPublishRole', { assumedBy: new iam.ServicePrincipal('lambda.amazonaws.com'), description: 'Role for sending notifications with minimal permissions', }); notificationRole.addToPolicy(new iam.PolicyStatement({ actions: ['sns:Publish'], resources: ['*'], effect: iam.Effect.ALLOW, })); } }
